-- Vistto · checklists das Fichas de Inspeção de Segurança (FIS · MF PTA) no lugar dos checklists criados pelo Claude (migração 19)
-- 22 tipos de máquina, 597 perguntas. Texto organizado; itens e seções iguais às fichas.
-- As perguntas antigas desses tipos são DESATIVADAS (ativo = false), não apagadas:
-- somem das inspeções novas, mas continuam aparecendo nas inspeções que já foram feitas.

update public.checklist_itens set ativo = false
 where tipo in ('vme-munck-csp', 'vme-caminhao-basculante-csp', 'vme-guindaste-csp', 'vme-conjunto-oxicort-csp', 'vme-compressor-csp', 'vme-compactador-de-solo-manual-csp', 'vme-esmeril-de-bancada-csp', 'vme-gerador-csp', 'vme-andaimes-csp', 'vme-maquina-de-solda-csp', 'vme-caminhao-perfuratriz-csp', 'vme-retroescavadeira-csp', 'vme-serra-circular-csp', 'vme-caminhao-comboio-csp', 'vme-carros-leve-e-4x4-csp', 'vme-caminhao-pipa-csp', 'vme-pemt-csp', 'vme-betoneira-csp', 'vme-escavadeira-hidraulica-20t-csp', 'vme-trator-pneu-esteira-csp', 'vme-caminhao-betoneira-csp', 'vme-motoniveladora-csp')
   and ativo and id not like 'f0%';

on conflict (id) do update set secao = excluded.secao, ordem = excluded.ordem, pergunta = excluded.pergunta, ativo = true;

notify pgrst, 'reload schema';
